        return

    L = int(input_data[0])
    C = int(input_data[1])
    P = int(input_data[2])

    black_cells = set()
    idx = 3
    for _ in range(P):
        r = int(input_data[idx])
        c = int(input_data[idx + 1])
        black_cells.add((r, c))
        idx += 2

    # Direções ortogonais
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Identificar casas elegíveis para receber peças brancas
    eligible_cells = set()
    for r, c in black_cells:
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 1 <= nr <= L and 1 <= nc <= C:
                if (nr, nc) not in black_cells:
                    eligible_cells.add((nr, nc))

    # Grafo bipartido dividido por paridade da soma (r + c)
    set_A = []  # Paridade ímpar
    set_B = []  # Paridade par

    for r, c in eligible_cells:
        if (r + c) % 2 == 1:
            set_A.append((r, c))
        else:
            set_B.append((r, c))

    adj = {u: [] for u in set_A}
    for u in set_A:
        r, c = u
        for dr, dc in directions:
            v = (r + dr, c + dc)
            if v in eligible_cells:
                adj[u].append(v)

    # Emparelhamento bipartido máximo (Kuhn's Algorithm)
    match_B = {}

    def dfs(u, visited):
        for v in adj[u]:
            if v not in visited:
                visited.add(v)
                if v not in match_B or dfs(match_B[v], visited):
                    match_B[v] = u
                    return True
        return False

    max_matching = 0
    for u in set_A:
        visited = set()
        if dfs(u, visited):
            max_matching += 1

    # Teorema de König: Tamanho do Conjunto Independente Máximo = |V| - Matching Máximo
    ans = len(eligible_cells) - max_matching
    print(ans)


if __name__ == "__main__":
    solve()
